//! Fetch-owned descriptions. Provider definitions are never rewritten here.
use serde_json::{Value,json};

pub fn definitions()->Vec<Value>{
    let reference=json!({"type":"object","properties":{"name":{"type":"string"},"credential_ref":{"type":"string"}},"required":["name","credential_ref"],"additionalProperties":false});
    let string=json!({"type":"string"});
    let properties=vec![
        ("fetch__discover_servers","Reads supported global Claude Code, Codex and OpenCode MCP definitions, or one absolute config_path. Requires server-management permission. Returns eligible rows and safe warnings; it does not install, start or log in to a server. Review the user's selection before installation.",json!({"config_path":string}),vec![]),
        ("fetch__install_servers","Prepares selected configured MCP servers in Fetch's private pinned package environments. Requires server-management permission. Supply exact config_path/server_name pairs from discovery. Returns an accepted installation_id; preparation is not authentication or readiness. Use get_installation to inspect this same operation; do not resubmit after an uncertain response.",json!({"servers":{"type":"array","minItems":1,"items":{"type":"object","properties":{"config_path":string,"server_name":string},"required":["config_path","server_name"],"additionalProperties":false}}}),vec!["servers"]),
        ("fetch__get_installation","Reads progress for one installation_id in the current Fetch run. Requires server-management permission. A pending response means keep monitoring the same ID; failed items preserve successful installations. Reading a failed operation is a successful read. Retry only failed entries after reviewing their failure.",json!({"installation_id":string}),vec!["installation_id"]),
        ("fetch__get_servers","Reads saved configuration, latest authentication/runtime state, pending changes and aggregate tool execution counts. Requires server-management permission. Optional id filters select exact server IDs; restart_id requires exactly one id and follows that named attempt through success or failure. Reads never start, authenticate or reconnect a server.",json!({"id":{"type":"array","items":string},"restart_id":string}),vec![]),
        ("fetch__list_tools","Lists installed tool definitions and reports unavailable servers or rejected tools. Valid remaining tools stay usable. Omit view to inspect this MCP client's catalog, or choose raw or a supported protocol view. Check complete, origins.status and rejected_tools before assuming every upstream tool is available. Requires catalog permission. Optional server_id filters select exact origins; a read never starts or authenticates a server.",json!({"server_id":{"type":"array","items":string},"view":{"enum":["raw","2025-11-25","2026-07-28"]}}),vec![]),
        ("fetch__authenticate_server","Starts the selected server's supported provider authentication flow. Requires server-management permission. Returns its structured state and any user handoff; manual values are entered only in native Fetch Settings. Browser consent and accepted login are not proof of verified stored credentials. Inspect the server state; do not open repeated login flows automatically.",json!({"server_id":string}),vec!["server_id"]),
        ("fetch__update_server_config","Saves common launch arguments, working directory, environment credential references, remote header references and Fetch execution settings. Requires server-management permission. Arrays replace their field; omitted values are unchanged. tool_timeouts_ms entries merge, and null removes an override. Accepts references only, never secret values. Execution settings apply to new calls; launch/header changes may require the explicit restart/reconnect operation. Saving does not restart or authenticate.",json!({"server_id":string,"args":{"type":"array","items":string},"working_directory":{"type":["string","null"]},"environment":{"type":"array","items":reference},"connection":{"type":"object","properties":{"headers":{"type":"array","items":reference}},"additionalProperties":false},"execution":{"type":"object","properties":{"max_concurrent_calls":{"type":"integer","minimum":1,"maximum":64},"default_timeout_ms":{"type":"integer","minimum":1,"maximum":86400000},"tool_timeouts_ms":{"type":"object","additionalProperties":{"type":["integer","null"],"minimum":1,"maximum":86400000}}},"additionalProperties":false}}),vec!["server_id"]),
        ("fetch__restart_server","Requests restart of an installed local server, or Connect/Reconnect for a saved remote connection. Requires server-management permission. An accepted restart_id is pending, not success; inspect get_servers with that exact ID. Default normal restart drains forwarded work. Explicit force_restart can interrupt local work or recover remote capacity while prior remote outcomes stay unknown; it cannot stop a hosted provider or undo actions. Never escalate to force or replay automatically.",json!({"server_id":string,"force_restart":{"type":"boolean"}}),vec!["server_id"]),
    ];
    properties.into_iter().map(|(name,description,properties,required)|json!({"name":name,"description":description,"inputSchema":{"type":"object","properties":properties,"required":required,"additionalProperties":false}})).collect()
}
pub fn scope(name:&str)->Option<&'static str>{match name{"fetch__list_tools"=>Some("fetch:catalog"),"fetch__discover_servers"|"fetch__install_servers"|"fetch__get_installation"|"fetch__get_servers"|"fetch__authenticate_server"|"fetch__update_server_config"|"fetch__restart_server"=>Some("fetch:manage"),_=>None}}
